mapper.select:
SELECT *
  FROM (
        SELECT DEVICE_ID      AS "deviceId"
             , ERR_GROUP_CD   AS "errGroupCd"
             , MODULE_TYPE_CD AS "moduleTypeCd"
             , FAULT_CLASS_CD AS "faultClassCd"
             , ERR_CD         AS "errCd"
          FROM T_FAULT_ANALYSIS
         WHERE TERM_GROUP_ID = #{termGroupId}
           AND TERM_ID       = #{termId}
           AND JNL_DATE      = #{jnlDate}
           AND JNL_TIME      = #{jnlTime}
         ORDER BY FAULT_CLASS_CD ASC
       )
 WHERE ROWNUM = 1
